def choose_move(observation):
    def get(obj, key, default=None):
        if isinstance(obj, dict):
            return obj.get(key, default)
        return default

    def as_point(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            x, y = v[0], v[1]
            if isinstance(x, (int, float)) and isinstance(y, (int, float)):
                return [x, y]
        return None

    def extract_points(value, out):
        if value is None:
            return
        p = as_point(value)
        if p is not None:
            out.append(p)
            return
        if isinstance(value, dict):
            for v in value.values():
                extract_points(v, out)
        elif isinstance(value, (list, tuple)):
            for v in value:
                extract_points(v, out)

    def sign(n):
        return (n > 0) - (n < 0)

    def sqdist(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    def nearest_dist(pos, points):
        best = None
        for p in points:
            d = sqdist(pos, p)
            if best is None or d < best:
                best = d
        return best

    me = None
    for k in ("self_pos", "agent_pos", "position", "pos", "loc", "location", "my_pos"):
        me = as_point(get(observation, k))
        if me is not None:
            break

    if me is None:
        me = [0, 0]

    resources = []
    goals = []
    enemies = []
    threats = []
    friends = []

    for k in ("resources", "resource_positions", "food", "coins", "items", "targets", "objectives", "goals",
              "territory_targets", "capture_points", "interest_points", "waypoints"):
        extract_points(get(observation, k), resources)

    for k in ("goal", "target", "objective"):
        extract_points(get(observation, k), goals)

    for k in ("enemies", "enemy_positions", "opponents", "adversaries", "chasers", "hunters"):
        extract_points(get(observation, k), enemies)

    for k in ("threats", "danger", "hazards"):
        extract_points(get(observation, k), threats)

    for k in ("allies", "friends", "teammates"):
        extract_points(get(observation, k), friends)

    # Merge lists while preserving order and removing duplicates
    def uniq(points):
        seen = set()
        out = []
        for p in points:
            key = (p[0], p[1])
            if key not in seen:
                seen.add(key)
                out.append(p)
        return out

    resources = uniq(resources)
    goals = uniq(goals)
    enemies = uniq(enemies)
    threats = uniq(threats)
    friends = uniq(friends)

    # Candidate move set
    candidates = [[-1, -1], [-1, 0], [-1, 1],
                  [0, -1], [0, 0], [0, 1],
                  [1, -1], [1, 0], [1, 1]]

    mode = str(get(observation, "mode", "")).lower()
    obs_text = mode + " " + str(observation).lower()

    # Heuristic intent
    pursuing = ("pursuit" in obs_text and ("evasion" not in obs_text)) or bool(get(observation, "is_pursuer", False))
    evading = ("evasion" in obs_text) or bool(get(observation, "is_evader", False))

    # If only enemies exist, opportunistically chase when pursuit-like; otherwise avoid.
    target_points = goals[:] if goals else resources[:]
    if not target_points:
        if pursuing and enemies:
            target_points = enemies[:]
        elif goals:
            target_points = goals[:]
        elif resources:
            target_points = resources[:]

    best_move = [0, 0]
    best_score = None

    for mv in candidates:
        nx = me[0] + mv[0]
        ny = me[1] + mv[1]
        np = [nx, ny]
        score = 0.0

        if target_points:
            d = nearest_dist(np, target_points)
            if d is not None:
                score += 20.0 / (1.0 + d)

        if resources:
            d = nearest_dist(np, resources)
            if d is not None:
                score += 12.0 / (1.0 + d)

        if goals:
            d = nearest_dist(np, goals)
            if d is not None:
                score += 15.0 / (1.0 + d)

        danger_points = enemies + threats
        if danger_points:
            d = nearest_dist(np, danger_points)
            if d is not None:
                if evading or not pursuing:
                    score -= 30.0 / (1.0 + d)
                else:
                    score += 8.0 / (1.0 + d)

        # Prefer movement over standing still when there is a clear direction.
        if mv != [0, 0]:
            score += 0.05

        # Slightly prefer smaller coordinate changes if tied.
        score -= 0.001 * (abs(mv[0]) + abs(mv[1]))

        if best_score is None or score > best_score:
            best_score = score
            best_move = mv

    return [int(best_move[0]), int(best_move[1])]

